mod support;
use support::session::Session;
#[test]
fn network_owner_completions_and_hover_use_exact_native_signatures(){
 for(owner,method,expected)in[("TcpListener","accept",&["Task<Result<[TcpStream, SocketAddress]","NetError"][..]),("TcpStream","split",&["Reader","Writer"][..]),("TcpStream","shutdownWrite",&["Task<Result<void","NetError"][..]),("UdpSocket","receiveFrom",&["Task<Result<Datagram","capacity"][..])]{let prefix=format!("import {{{owner}}} from 'std:net';async function inspect(value:Mutable<{owner}>):Task<void>{{value.");let suffix=if method=="receiveFrom"{"(1);}function main(){}"}else{"();}function main(){}"};let source=format!("{prefix}{method}{suffix}");let mut baseline=None;for broken in [false,true]{let source=if broken{format!("{source}function broken(){{const = ;}}") }else{source.clone()};let mut session=Session::start(&[]);session.open("main.tsr",&source);session.settle();let hover=session.hover("main.tsr",&source,prefix.len()+1).unwrap_or_default();assert!(hover.contains("Ownership:")&&expected.iter().all(|word|hover.contains(*word)),"{owner}.{method}: {hover}");let items=session.completion("main.tsr",&source,prefix.len()).unwrap();assert!(items.iter().any(|item|item==method));if let Some(prior)=&baseline{assert_eq!(&hover,prior);}else{baseline=Some(hover);}}}
}
#[test]
fn full_tcp_stream_is_documented_on_existing_io_parameter_help(){let source="import {readInto} from 'std:io';import {TcpStream} from 'std:net';import {Bytes} from 'std:bytes';async function inspect(stream:Mutable<TcpStream>,bytes:Mutable<Bytes>):Task<void>{unwrap(await readInto(stream,bytes));}function main(){}";let mut session=Session::start(&[]);session.open("main.tsr",source);session.settle();let at=source.rfind("readInto(").unwrap();let hover=session.hover("main.tsr",source,at+1).unwrap();assert!(hover.contains("TcpStream")&&hover.contains("IoError"),"{hover}");}
